(function(root){
'use strict';
function parseCSV(text){
 text=String(text).replace(/^\uFEFF/,'');let rows=[],row=[],cell='',quoted=false,closed=false;
 for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++;}else{quoted=false;closed=true;}}else cell+=c;}else if(c==='"'){if(cell||closed)throw Error('Unexpected quote in CSV.');quoted=true;}else if(c===','){row.push(cell);cell='';closed=false;}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()!==''))rows.push(row);row=[];cell='';closed=false;}else{if(closed&&!/\s/.test(c))throw Error('Unexpected text after a quoted field.');if(!closed)cell+=c;}}
 if(quoted)throw Error('Unclosed quote in CSV.');row.push(cell);if(row.some(v=>v.trim()!==''))rows.push(row);if(!rows.length)throw Error('CSV is empty.');const headers=rows.shift().map(x=>x.trim().toLowerCase());if(new Set(headers).size!==headers.length||headers.some(x=>!x))throw Error('CSV headers must be unique and non-empty.');return {headers,rows:rows.map((r,i)=>{if(r.length!==headers.length)throw Error('Record '+(i+2)+' has '+r.length+' fields; expected '+headers.length+'.');return Object.fromEntries(headers.map((h,j)=>[h,r[j].trim()]));})};
}
function requireColumns(parsed,cols){for(const c of cols)if(!parsed.headers.includes(c))throw Error('Missing column: '+c+'.');if(!parsed.rows.length)throw Error('CSV contains no data rows.');}
function cents(value){const v=String(value).trim();if(!/^-?\d+(?:\.\d{1,2})?$/.test(v))return null;const neg=v.startsWith('-');const [a,b='']=v.replace(/^-/,'').split('.');const n=Number(a)*100+Number(b.padEnd(2,'0'));return Number.isSafeInteger(n)?(neg?-n:n):null;}
function priceList(parsed,overrides=false){requireColumns(parsed,overrides?['department','item','unit_price']:['item','unit_price']);const map=new Map();for(const [i,r] of parsed.rows.entries()){const n=cents(r.unit_price);if(!r.item||n===null||n<0||(overrides&&!r.department))throw Error('Invalid price in record '+(i+2)+'. Use non-negative prices with up to 2 decimals.');const k=overrides?JSON.stringify([r.department,r.item]):r.item;if(map.has(k))throw Error('Duplicate price for '+r.item+' in record '+(i+2)+'.');map.set(k,n);}return map;}
function validate(parsed,prices,patches=new Map()){
 requireColumns(parsed,['department','item','quantity','sale_total']);return parsed.rows.map((r,i)=>{const total=cents(r.sale_total);const q=/^\d+$/.test(r.quantity)?Number(r.quantity):NaN;const key=JSON.stringify([r.department,r.item]);const override=patches.has(key);const unit=override?patches.get(key):prices.get(r.item);let expected=null,issue='';if(!r.department||!r.item)issue='Missing field';else if(!Number.isSafeInteger(q)||q<=0)issue='Invalid quantity';else if(total===null||total<0)issue='Invalid amount';else if(unit===undefined)issue='Unknown item';else {expected=unit*q;if(!Number.isSafeInteger(expected)){expected=null;issue='Amount too large';}else if(total!==expected)issue='Price mismatch';}return {...r,row:i+2,quantity:Number.isSafeInteger(q)?q:r.quantity,recorded:total,expected,unit,override,issue,valid:!issue};});
}
function summarize(rows){let revenue=0,valid=0;const departments=new Map();for(const r of rows){if(!departments.has(r.department))departments.set(r.department,{name:r.department||'(Missing department)',revenue:0,total:0,valid:0,flagged:0});const d=departments.get(r.department);d.total++;if(r.valid){valid++;revenue+=r.recorded;d.valid++;d.revenue+=r.recorded;if(!Number.isSafeInteger(revenue)||!Number.isSafeInteger(d.revenue))throw Error('Combined sales exceed the supported amount. Split the file into smaller batches.');}else d.flagged++;}return {total:rows.length,valid,flagged:rows.length-valid,revenue,rate:rows.length?valid/rows.length*100:0,departments:[...departments.values()].sort((a,b)=>b.revenue-a.revenue)};}
function csv(rows){return rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
const api={parseCSV,requireColumns,cents,priceList,validate,summarize,csv};if(typeof module!=='undefined')module.exports=api;else root.SalesCore=api;
})(typeof window!=='undefined'?window:globalThis);
